insert into fitness_private.challenge_definition_staging (part, txt) values (1, $def${"schema":"fitapp.challenge/1","id":"oap","version":"1.0.0","engine":">=1.0.0 <2.0.0","title":{"en":"One-arm pull-up","nl":"Van twaalf naar één"},"summary":{"en":"Strict one-arm pull-up in the chosen grip. Heavy weighted pulling plus unilateral skill work from week one, criteria-gated phases, 5-week blocks (4 build weeks + 1 deload week that ends with a test day replacing session B).","nl":"Strikte one-arm pull-up in de gekozen grip. Zwaar gewogen trekken plus eenarmig vaardigheidswerk vanaf week één, fasen met criteria, blokken van 5 weken (4 opbouw + 1 terugschakelweek met testdag in plaats van sessie B)."},"provenance":{"sources":[{"id":"artifact","ref":"claude.ai artifact B56eCk6wQMfAgSXBTCwmpW 'Van twaalf naar één'","asOf":"2026-10-07","role":"program rules, tag A"},{"id":"todoist","ref":"Todoist project 'One-arm pull-up' task descriptions (sessie A, sessie B, sessie C, Testdag, Hangen, Core)","asOf":"2026-10-07","role":"program details the artifact lacks, tag A (DECISIONS.md section 4)"},{"id":"decisions","ref":"docs/DECISIONS.md","asOf":"2026-10-07","role":"user decisions D1-D16, defaults F1-F27 and canonical resolutions C1-C65 (including the cross-document resolutions C37-C65 of the spec pass), tag D"},{"id":"research","ref":"docs/research/challenge_engine.md","asOf":"2026-10-07","role":"proposals (tag P) and engine defaults (tag E)"}],"evidenceNote":"The 65-75 % BW threshold, the 20 s hang and 8 s top-hold gates are coach heuristics (Kavadlo, StrongFirst forum, Willoughby), not research. The machine offset of 6.5 kg is the user's estimate ('6-7 kg'). All P-tagged rules are proposals that the user approves one by one (D8).","tagLegend":{"A":"Taken from the artifact or the Todoist task descriptions; executed as written unless the P proposal that supersedes it is approved (D8, C48). Generic load-jump caps do not limit these RULE-mode loads; a step above the generic cap raises warning WE-S2 at WARN severity and is logged (D13, C45). In-session A rules change the remaining sets immediately and can be undone (D14, C46).","P":"Proposal by the app design; active only when the user approved it (param approved_<proposalId> = true). Decisions are stored per proposal id; one proposal may switch several rules (C48). Undecided proposals are inactive.","D":"Fixed by docs/DECISIONS.md (user decision or canonical resolution); not a program rule from the artifact and not a proposal.","E":"Engineering default needed to execute an A rule deterministically; does not change training content."}},"challengeRules":{"start":"dead_hang_full_extension","implements":["bar","fixed_handle"],"forbidden":["free_hanging_ring","free_hand_contact","kip","bent_arm_start"],"finish":"chin_over_bar","return":"controlled_to_full_extension","grip":"free_choice_fixed_at_onboarding","agreedWithOpponentOn":"2026-08-31","attemptChecklist":[{"en":"Started from a dead hang with the arm fully extended (no kip, no pre-bend)","nl":"Gestrekte start, geen kip"},{"en":"Bar or fixed handle (no free-hanging ring)","nl":"Stang of vast handvat"},{"en":"Free hand touched nothing","nl":"Vrije hand raakt niets"},{"en":"Chin over the bar","nl":"Kin boven de stang"},{"en":"Controlled return to full extension","nl":"Gecontroleerd terug naar gestrekt"}]},"proposals":[{"id":"P01","title":{"en":"Gate the weekly session-A pin decrease"},"rationale":{"en":"An unconditional -5 lb per week is about +4.9 % one-arm load per week; gating it on completed sets and adding +5 lb after two failed weeks mirrors the program's own 90-degree-hold logic."},"ifDeclined":{"en":"The pin drops 5 lb (10 lb after a controlled calibration negative) after every session A in a normal week, as written."},"recommended":"approve","supersedes":["prog.A.pin.weekly"],"affects":{"rules":["prog.A.pin.gated"],"params":["aFailsToRaise"]}},{"id":"P02","title":{"en":"Definition of a missed week"},"rationale":{"en":"The program says 'missed week: no make-up, same weights' but never defines 'missed'; proposal: a session counts when at least half of its working sets were logged, and a week counts when at least 2 of the 3 required sessions count."},"ifDeclined":{"en":"A week is missed only when no challenge session at all was completed in it."},"recommended":"approve","supersedes":[],"affects":{"derived":["weekCounts"],"params":["minSessionsForWeek","sessionCountsRatio"]}},{"id":"P03","title":{"en":"Definition of an 'easy' session C"},"rationale":{"en":"Session C drops 5 lb after two easy sessions in a row but 'easy' is undefined; proposal: all 3 x 5 per arm done with at least 3 reps in reserve on every set (target is 2), or you tapped 'too easy'."},"ifDeclined":{"en":"Only an explicit 'too easy' tap on the exercise counts as easy."},"recommended":"approve","supersedes":[],"affects":{"derived":["cEasy"],"params":["cEasyMinRir"]}},{"id":"P04","title":{"en":"Definition of 'progress' for the stall rule"},"rationale":{"en":"'Two test days without progress' needs a metric; proposal: e1RM +1.0 kg, or weaker-arm hang +2 s, or weaker-arm top hold +1 s, or weaker-arm least assistance 5 lb lower, versus the previous valid test."},"ifDeclined":{"en":"Any strict improvement in any of those four metrics counts as progress."},"recommended":"approve","supersedes":[],"affects":{"derived":["testProgress"],"params":["progressEpsE1rm","progressEpsHang","progressEpsTopHold","progressEpsAssist"]}},{"id":"P05","title":{"en":"In-block progression for A 4 x 4 and C 4 x 5"},"rationale":{"en":"Only B has an in-block rule; proposal: +2.5 kg next week when every set reached its target reps with at least 2 reps in reserve and no grip slip (same rule as B)."},"ifDeclined":{"en":"A and C weighted loads stay fixed until the next test day."},"recommended":"approve","supersedes":[],"affects":{"rules":["prog.wpu.A","prog.wpu.C"],"params":["inBlockStepKg","inBlockMinRir"]}},{"id":"P06","title":{"en":"One-arm dead hang target from your latest fresh hang"},"rationale":{"en":"The C hang (4 x 10 s per arm) is 'reviewed on test day' without a formula; proposal: floor(0.67 x weaker-arm test-day hang), at least 10 s, at most +5 s per test, at most 30 s (15 s fresh -> 10 s, as now)."},"ifDeclined":{"en":"The target stays 10 s; the test-day summary asks you whether to change it."},"recommended":"approve","supersedes":[],"affects":{"rules":["data.test.hangTarget"],"params":["hangTargetFraction","hangTargetMin","hangTargetMax","hangTargetMaxStep"]}},{"id":"P07","title":{"en":"Block-relative test dates"},"rationale":{"en":"Each block is 5 weeks counted from the test actually done (matches the Todoist 'every 5 weeks' recurrence); the artifact's fixed table would make block 2 only 4 weeks after the postponed first test (F9)."},"ifDeclined":{"en":"Tests follow the fixed date list from the artifact (8 Nov, 13 Dec 2026, 17 Jan, 21 Feb, 28 Mar, 2 May 2027)."},"recommended":"approve","supersedes":["struct.deload.enter.fixed"],"affects":{"rules":["struct.deload.enter"]}},{"id":"P08","title":{"en":"Max strict reps moved to the end of the test day"},"rationale":{"en":"A set of 18+ reps drains grip before the one-arm hang and top-hold tests; testing it last protects the gate metrics (F10)."},"ifDeclined":{"en":"Todoist order: 3RM, max reps, hang, top hold, least assistance."},"recommended":"approve","supersedes":[],"affects":{"templates":["T1"]}},{"id":"P09","title":{"en":"Negatives keep their own 8 s / 5 s progression"},"rationale":{"en":"With the personal curve (D7) the 105 % formula would drop negatives from 47.5 to 42.5 kg although they progress on their own rule; proposal: the test-day recalculation never lowers them if at least one valid negative session was logged in the block, and the reset level moves up 5 kg with each increase."},"ifDeclined":{"en":"On each test day negatives = 105 % of the gate e1RM (rounded down) and the reset level = that minus 2.5 kg; the reset level does not follow increases."},"recommended":"approve","supersedes":["data.test.neg"],"affects":{"rules":["data.test.neg.keep","prog.B.negReset.follow"]}},{"id":"P10","title":{"en":"Test-day recalculation of the anchor and A/B loads via the personal curve"},"rationale":{"en":"The program recalculates working weights on test day without a formula for the anchor; proposal: anchor = anchorFraction x new 1RM total - bodyweight (anchorFraction frozen at import, so today's 20 kg is reproduced), kg per rep = slope of your curve at the anchor, A = anchor + 1 rep, B = anchor + 3 reps, each change clamped to +/-5 kg."},"ifDeclined":{"en":"The anchor stays the last measured C load; A = anchor + 1 x 2.17 kg and B = anchor + 3 x 2.17 kg, unclamped."},"recommended":"approve","supersedes":["data.test.loads"],"affects":{"rules":["data.test.loads.curve"],"params":["maxRecalcJumpKg"]}},{"id":"P11","title":{"en":"Pins from the least-assistance test"},"rationale":{"en":"Proposal: A pin = weaker-arm least-assist pin + 10 lb, C pin = A + 10 lb, 90-degree hold pin = A - 5 lb (reproduces today's 40 / 50 / 35 lb pattern and the original 35 + 10 = 45 lb start)."},"ifDeclined":{"en":"Pins are not recalculated on test day; they continue from their weekly rules."},"recommended":"approve","supersedes":[],"affects":{"rules":["data.test.pins"],"params":["pinOffsetA","pinOffsetC","pinOffsetHold90"]}},{"id":"P12","title":{"en":"In-session grind rule for B"},"rationale":{"en":"A B set with fewer than 2 reps or 0 reps in reserve means the load is above today's capacity; taking 2.5 kg off the remaining sets avoids failure on weighted pulls (D10). Like every in-session challenge rule it applies immediately and shows 'Rule: ... · Undo' (D14, C46)."},"ifDeclined":{"en":"No automatic change; you decide."},"recommended":"approve","supersedes":[],"affects":{"inSessionRules":["ins.B.wpu.grind"],"params":["bGrindStepKg"]}},{"id":"P13","title":{"en":"In-session +5 lb for the A machine after a failed set"},"rationale":{"en":"After the calibration set, a set where the weaker arm got 2 or more reps below target adds 5 lb assistance to the remaining sets, to stop grinding one-arm reps. It applies immediately and can be undone (D14, C46)."},"ifDeclined":{"en":"Only the first-set calibration adjusts the pin during the session."},"recommended":"approve","supersedes":[],"affects":{"inSessionRules":["ins.A.oaa.fail"],"params":["oaaFailMargin"]}},{"id":"P14","title":{"en":"Injury exit needs 3 pain-free days"},"rationale":{"en":"The elbow protocol ends after two weeks; proposal: only if the last 3 days were pain-free, otherwise extend by 7 days and advise a physiotherapist."},"ifDeclined":{"en":"The protocol ends after exactly 14 days."},"recommended":"approve","supersedes":["safety.injury.exit"],"affects":{"rules":["safety.injury.exit.painfree","safety.injury.extend"],"params":["painFreeDaysToExit","injuryExtendDays"]}},{"id":"P15","title":{"en":"Pause handling"},"rationale":{"en":"After a pause of 7 days or more the current week repeats with the same loads and the test waits for a clean session; after 28 days or more the block-start loads are restored and the block restarts at week 1."},"ifDeclined":{"en":"Any pause resumes the same week with the same loads; the test waits for a clean session."},"recommended":"approve","supersedes":["struct.resume.interrupt"],"affects":{"rules":["struct.resume.repeat","struct.resume.restart"],"params":["pauseRepeatDays","pauseRestartDays"]}},{"id":"P16","title":{"en":"Completion with either arm"},"rationale":{"en":"The challenge against your friend is 'one rep'; one valid rep with either arm completes it."},"ifDeclined":{"en":"A valid rep with each arm is required."},"recommended":"approve","supersedes":[],"affects":{"phases":[3]}},{"id":"P17","title":{"en":"Three ladders in the 1-2-3 variant of B"},"rationale":{"en":"The stall step switches B to ladders of 1-2-3 without a count; 3 ladders = 18 reps, close to the 6 x 2 = 12 reps plus the extra singles."},"ifDeclined":{"en":"The app asks for the number of ladders when the variant activates."},"recommended":"approve","supersedes":[],"affects":{"params":["ladderCount"],"templates":["B1"]}},{"id":"P18","title":{"en":"Phase 2 and 3 sessions as drafts"},"rationale":{"en":"Phases 2 and 3 are only sketched; encode drafts now (machine to finger ladder, three-angle holds, typewriters if a wide bar exists, attempts first in phase 3) and refine them with you before gate 1 can realistically pass."},"ifDeclined":{"en":"After a gate pass the phase-1 sessions continue until the definition is revised."},"recommended":"approve","supersedes":[],"affects":{"templates":["C2","A2","A3","B3","C3","T2"],"rules":["prog.finger"]}},{"id":"P19","title":{"en":"Test-pending weeks stay deload weeks"},"rationale":{"en":"When the test is postponed, the waiting week keeps the deload format (half sets, same loads) so you arrive fresh at the test."},"ifDeclined":{"en":"Waiting weeks use the full build sessions."},"recommended":"approve","supersedes":[],"affects":{"modes":["test_pending"]}},{"id":"P20","title":{"en":"One-arm 5 s negative placed after least assistance on test day"},"rationale":{"en":"The phase-1 gate needs the negative on a test day, so it is part of every test day (C65) although the Todoist order omits it; testing it right after least assistance keeps it away from the hang and top-hold tests and before max reps when P08 moves them to the end. Since C65 the definition fixes the test-day order, so this proposal confirms the place the template already gives it."},"ifDeclined":{"en":"The negative keeps its place in the test template (right after least assistance); the test-day wizard has no free order (C65)."},"recommended":"approve","supersedes":[],"affects":{"templates":["T1"]}},{"id":"P21","title":{"en":"Test protocols for least assistance and the 3RM"},"rationale":{"en":"Least assistance: start at the A pin + 10 lb, -5 lb after each clean rep, stop at the first failure, max 5 attempts per arm, 3 min rest. 3RM: ramp 50 / 70 / 85 % of the expected 3RM total, then +2.5 kg attempts, max 3 working attempts, 4 min rest."},"ifDeclined":{"en":"The wizard only states the goal ('least assistance for one clean rep', 'heaviest clean triple')."},"recommended":"approve","supersedes":[],"affects":{"templates":["T1"]}},{"id":"P22","title":{"en":"Plank plate size"},"rationale":{"en":"After 30 s the program adds 'a plate on the upper back' without a size; proposal: 5 kg."},"ifDeclined":{"en":"The app asks for the plate weight when the step is reached."},"recommended":"approve","supersedes":[],"affects":{"params":["plankPlateKg"],"rules":["prog.plank"]}},{"id":"P23","title":{"en":"24 h protected window after B for elbow flexors"},"rationale":{"en":"B is the heaviest elbow-flexor session (weighted 6 x 2 plus 47.5 kg negatives); no curls or heavy grip work in the 24 h after it (C12 marks this window as a proposal)."},"ifDeclined":{"en":"No window after B."},"recommended":"approve","supersedes":[],"affects":{"integration":["pw.afterB"]}},{"id":"P24","title":{"en":"B returns to 6 x 2 after a test with progress"},"rationale":{"en":"The ladder variant is a stall remedy; once a test shows progress again, B returns to the standard 6 x 2 progression."},"ifDeclined":{"en":"B stays on ladders until you change it."},"recommended":"approve","supersedes":[],"affects":{"rules":["struct.stall.revert"]}},{"id":"P25","title":{"en":"Definition of a 'clean session'"},"rationale":{"en":"The test waits for 'a normal session without complaints'; proposal: an A, B or C session with at least 80 % of its working sets logged and no pain report."},"ifDeclined":{"en":"Any completed A, B or C session without a pain report counts."},"recommended":"approve","supersedes":[],"affects":{"rules":["struct.cleanSession"],"params":["cleanSessionRatio"]}},{"id":"P26","title":{"en":"Day of the weekly fresh two-arm hang measurement"},"rationale":{"en":"The daily hang task says 'measure your best time fresh once a week' without a day; proposal: Monday (or the first day of the week without a gym session)."},"ifDeclined":{"en":"You pick the day each week (a 'measure today' toggle on the hang task)."},"recommended":"approve","supersedes":[],"affects":{"habits":["daily_hang"],"params":["hangMeasureWeekday"]}},{"id":"P27","title":{"en":"What 'light bilateral' means during the elbow protocol"},"rationale":{"en":"The protocol says 'no unilateral work, keep training bilaterally light'; proposal: pull-ups at bodyweight, rows and dips with at least 3 reps in reserve, half the sets, prehab doubled."},"ifDeclined":{"en":"Unilateral and eccentric items are removed; the remaining items keep their loads with a 'keep it light' note."},"recommended":"approve","supersedes":[],"affects":{"modes":["injury"]}}],"params":{"approved_P01":{"type":"bool","default":false,"tag":"P","proposal":"P01","userEditable":true},"approved_P02":{"type":"bool","default":false,"tag":"P","proposal":"P02","userEditable":true},"approved_P03":{"type":"bool","default":false,"tag":"P","proposal":"P03","userEditable":true},"approved_P04":{"type":"bool","default":false,"tag":"P","proposal":"P04","userEditable":true},"approved_P05":{"type":"bool","default":false,"tag":"P","proposal":"P05","userEditable":true},"approved_P06":{"type":"bool","default":false,"tag":"P","proposal":"P06","userEditable":true},"approved_P07":{"type":"bool","default":false,"tag":"P","proposal":"P07","userEditable":true},"approved_P08":{"type":"bool","default":false,"tag":"P","proposal":"P08","userEditable":true},"approved_P09":{"type":"bool","default":false,"tag":"P","proposal":"P09","userEditable":true},"approved_P10":{"type":"bool","default":false,"tag":"P","proposal":"P10","userEditable":true},"approved_P11":{"type":"bool","default":false,"tag":"P","proposal":"P11","userEditable":true},"approved_P12":{"type":"bool","default":false,"tag":"P","proposal":"P12","userEditable":true},"approved_P13":{"type":"bool","default":false,"tag":"P","proposal":"P13","userEditable":true},"a